/* @lc app=leetcode id=2416 lang=kotlin */
class Solution { fun sumPrefixScores(words: Array<String>): IntArray = words.sumOf { it.length }.let { totalLen -> IntArray((totalLen + 1) * 26).let { trie -> IntArray(totalLen + 1).let { counts -> IntArray(1) { 1 }.let { nxt -> words.forEach { w -> w.fold(0) { cur, c -> (c - 'a').let { ch -> (if (trie[cur * 26 + ch] == 0) nxt[0]++.also { trie[cur * 26 + ch] = it } else trie[cur * 26 + ch]).also { counts[it]++ } } } }.run { words.map { w -> w.fold(0 to 0) { (cur, sum), c -> trie[cur * 26 + (c - 'a')].let { it to sum + counts[it] } }.second }.toIntArray() } } } } } }